import json, re

def lastnum_full(s):
    ans = re.findall(r"-?\d[\d,]*\.?\d*", s)
    return ans[-1] if ans else None
def numeq(x, gt):
    try: return x is not None and abs(float(x.replace(',',''))-float(gt))<1e-9
    except: return False
def correct_somewhere_tail(s, gt, tail=300):
    # does the correct answer appear as a standalone number in the last `tail` chars?
    tail_s = s[-tail:]
    nums = re.findall(r"-?\d[\d,]*\.?\d*", tail_s)
    return any(numeq(n, gt) for n in nums)

def analyze(path,label):
    rows=[json.loads(l) for l in open(path)]
    n=len(rows)
    grader=0; ans_in_tail_not_last=0; truncated_like=0
    for r in rows:
        out, gt = r['output'], str(r['gts'])
        ln = lastnum_full(out)
        if numeq(ln, gt): grader+=1
        elif correct_somewhere_tail(out, gt):
            ans_in_tail_not_last+=1
    print(f"{label:12s} n={n} grader_ok={grader/n:.4f}  correct-num-in-tail-but-not-last={ans_in_tail_not_last} ({ans_in_tail_not_last/n:.3f})")

for s in [1,30,60]: analyze(f'rollouts/{s}.jsonl', f'train_s{s}')
for s in [0,30,60]: analyze(f'val_generations/{s}.jsonl', f'val_s{s}')
EOF

