"""GSM8K reward: 1.0 when the last number in the response equals the reference answer."""
import re

# An optionally negative integer or decimal, allowing thousands separators,
# e.g. "-3", "72", "72.0", "1,000", "1,000.50".
_NUMBER_RE = re.compile(r"-?\d[\d,]*\.?\d*")


def _to_float(token):
    """Parse a number token numerically (dropping thousands separators), or None."""
    token = token.replace(",", "").rstrip(".")
    if not token or token in ("-", "."):
        return None
    try:
        return float(token)
    except ValueError:
        return None


def _last_number(text):
    """Return the numeric value of the last number contained in `text`, or None."""
    for token in reversed(_NUMBER_RE.findall(str(text))):
        value = _to_float(token)
        if value is not None:
            return value
    return None


def compute_score(data_source, solution_str, ground_truth, extra_info=None, **kwargs):
    """Score 1.0 iff the last number in the response equals the gold answer numerically.

    The comparison is numeric (so "72.0" or "1,000" match a gold "72" / "1000") and
    considers the entire response (no truncation of long answers), matching how
    GSM8K accuracy is graded on held-out data.
    """
    answer = _last_number(solution_str)
    if answer is None:
        return 0.0
    target = _last_number(ground_truth)
    if target is None:
        return 0.0
    return 1.0 if abs(answer - target) < 1e-6 else 0.0

